 $$('[data-page]').forEach(b=>{const active=b.dataset.page===page||(b.dataset.page==='more'&&['records','payments','settings'].includes(page));b.classList.toggle('active',active);active?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current')});
