 $('#tenant-table').innerHTML=`<table><thead><tr><th>PENGHUNI</th><th>KAMAR</th><th>KESEPAKATAN TERAKHIR</th><th>AKHIR PERIODE</th><th></th></tr></thead><tbody>${list.map(t=>{const agreement=t.agreements.at(-1),end=termEnd({...t,day:agreement.day},agreement.start.slice(0,7),agreement.months);return `<tr><td><b>${esc(t.name)}</b><small>${esc(t.phone)}${t.endDate?' · Keluar '+esc(t.endDate):''}</small></td><td>${esc(room(t).name)}</td><td><span class="badge paid">${agreement.months} bulan</span><small>${money(agreement.total)} total tenure</small></td><td>${dateLabel(end)}<small>Mulai ${esc(agreement.start)}</small></td><td><div class="table-actions"><button class="text-button" onclick="tenantDetail('${t.id}')">Riwayat</button><button class="text-button" onclick="editTenant('${t.id}')">Edit →</button></div></td></tr>`}).join('')}</tbody></table>${list.length?'':empty('Penghuni tidak ditemukan.')}`;
