 return notice+summary+`<section class="panel">${head}<div class="table-wrap annual-scroll" tabindex="0" aria-label="Ledger 12 bulan, geser untuk melihat bulan lainnya"><table class="annual-ledger"><thead><tr><th class="ledger-sticky">PENGHUNI / KAMAR</th>${periods.map(reference=>`<th>${periodName(reference)}</th>`).join('')}</tr></thead><tbody>${all.map(t=>`<tr data-tenant="${t.id}"><td class="ledger-sticky"><b>${esc(t.name)}</b><small>Kamar ${esc(room(t).name)}</small></td>${periods.map(reference=>{const entry=ledgerEntry(t,reference);return `<td>${entry.active?`<button class="ledger-cell ${entry.payment?.status==='paid'?'settled':entry.payment?'awaiting':''}" data-period="${reference}" onclick="openLedgerMonth('${t.id}','${reference}')" aria-label="${esc(t.name)}, ${periodName(reference)}, tagihan ${money(entry.charge)}, terbayar ${money(entry.paid)}, sisa ${money(entry.balance)}"><span>Tagihan <b>${money(entry.charge)}</b></span><span class="ledger-paid">Terbayar <b>${money(entry.paid)}</b></span><span class="${entry.balance?'ledger-outstanding':'ledger-paid'}">Sisa <b>${money(entry.balance)}</b></span>${['review','deferred'].includes(entry.payment?.status)?'<small>Perlu verifikasi</small>':''}</button>`:'<span class="ledger-inactive">Di luar periode sewa</span>'}</td>`}).join('')}</tr>`).join('')}</tbody><tfoot><tr><th class="ledger-sticky">TOTAL PER BULAN</th>${periods.map(reference=>{const total=ledgerTotals(all,reference);return `<td><div class="ledger-cell ledger-total"><span>Tagihan <b>${money(total.charge)}</b></span><span class="ledger-paid">Terbayar <b>${money(total.paid)}</b></span><span>Sisa <b>${money(total.balance)}</b></span></div></td>`}).join('')}</tr></tfoot></table></div>${all.length?'':empty('Belum ada penghuni.')}</section><p class="ledger-footnote">Tanggal transfer dan tanggal jatuh tempo tenure tetap tercatat di detail. Ledger ini membagi nilai sewa ke bulan yang ditanggung; ini bukan daftar arus kas transfer per bulan.</p>`;
