function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function editTenant(id){
 const t=state.tenants.find(x=>x.id===id),available=state.rooms.filter(r=>!state.tenants.some(x=>!x.endDate&&x.room===r.id&&x.id!==id));
 if(!available.length){toast('Tambahkan kamar tersedia terlebih dahulu.');return}
 const anchor=t?.termStart|| (t?localDate(Billing.date(t.start.slice(0,7),t.day)):localDate(today));
 modal(t?'Edit penghuni':'Penghuni baru',`<form id="tenant-form"><div class="form-grid"><label class="full">Nama lengkap<input name="name" required maxlength="70" value="${esc(t?.name||'')}" placeholder="Contoh: Nadia Putri"></label><label class="full">Nomor WhatsApp<input name="phone" type="tel" required pattern="[0-9+ ]{9,20}" value="${esc(t?.phone||'')}" placeholder="08… atau +62…"></label><label>Kamar<select name="room">${available.map(r=>`<option value="${r.id}" ${t?.room===r.id?'selected':''}>${esc(r.name)} · ${money(r.price)}</option>`).join('')}</select></label><label>Tenure / lama sewa<select name="term" id="tenant-term">${termOptions(t?Billing.term(t):1)}</select></label><label class="full">Total harga sewa untuk seluruh tenure (Rp)<input type="number" name="termRate" required min="1" step="1" value="${t?.termRate||room(t||{room:available[0].id}).price}"><small class="field-help">Contoh: Rp6.000.000 untuk 6 bulan → Rp1.000.000 per bulan.</small></label><label>Mulai menghuni<input type="date" name="start" required value="${t?.start||localDate(today)}"></label><label>Awal periode sewa ini<input type="date" name="termStart" required value="${anchor}"></label></div><div class="hint" id="term-preview" aria-live="polite"></div><p style="font-size:10px">Jatuh tempo mengikuti awal kesepakatan yang disimpan. Tanggal 29–31 menyesuaikan akhir bulan. Gunakan Perpanjangan sewa untuk menyimpan periode berikutnya. Catatan pembayaran lama tetap tersimpan.</p><div class="actions"><button type="button" class="secondary" onclick="closeModal()">Batal</button><button class="primary">Simpan penghuni</button></div></form>`);
 const form=$('#tenant-form');
 function preview(){const anchor=form.elements.termStart.value,months=Number(form.elements.term.value),total=Number(form.elements.termRate.value);if(!anchor||!Number.isSafeInteger(total)||total<=0)return;const day=Number(anchor.slice(8,10)),next=Billing.date(Billing.shift(anchor.slice(0,7),months),day),end=new Date(next);end.setDate(end.getDate()-1);const first=Billing.split(total,months,0),last=Billing.split(total,months,months-1);$('#term-preview').innerHTML=`<b>${money(total)} total untuk ${months} bulan</b><br>Tagihan per bulan: ${money(last)}${first!==last?' – '+money(first):''}<br>Periode: ${dateLabel(Billing.date(anchor.slice(0,7),day))} – ${dateLabel(end)}<br>Perpanjangan berikutnya: ${dateLabel(next)}${first!==last?'<br>Selisih pembulatan Rp1 dibagi ke bulan-bulan awal.':''}`}
 form.oninput=preview;form.onchange=preview;
 form.elements.start.onchange=()=>{if(!t)form.elements.termStart.value=form.elements.start.value;preview()};preview();
 form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),termStart=f.get('termStart'),data={id:id||crypto.randomUUID(),name:f.get('name').trim(),phone:f.get('phone').trim(),room:f.get('room'),day:t&&termStart===anchor?t.day:Number(termStart.slice(8,10)),term:Number(f.get('term')),termRate:Number(f.get('termRate')),termStart,start:f.get('start')};if(!data.name)return;if(data.termStart<data.start)return toast('Awal periode tidak boleh sebelum mulai menghuni.');if(!Number.isSafeInteger(data.termRate)||data.termRate<=0)return toast('Isi total harga sewa yang valid.');if(t&&data.termStart!==anchor)return toast('Gunakan Perpanjangan sewa untuk membuat periode berikutnya.');if(t&&(data.term!==t.term||data.termRate!==t.termRate)&&state.payments.some(p=>p.tenant===id&&p.status!=='rejected'&&Billing.covered(p).some(m=>m>=termStart.slice(0,7))))return toast('Kesepakatan ini memiliki pembayaran aktif. Selesaikan koreksi pembayaran sebelum mengubah harga atau tenure.');data.agreements=[...(t?.agreements||[]).filter(item=>item.start.slice(0,7)!==termStart.slice(0,7)),{start:termStart,months:data.term,total:data.termRate,day:data.day}].sort((a,b)=>a.start.localeCompare(b.start));if(mutateAndSave(()=>{if(t)Object.assign(state.tenants.find(item=>item.id===id),data);else state.tenants.push(data)})){closeModal();render();toast('Data penghuni dan tenure tersimpan.')}};
}
function editRoom(id){let r=state.rooms.find(r=>r.id===id);modal(r?'Edit kamar':'Kamar baru',`<form id="room-form"><label>Nomor / nama kamar<input name="name" required maxlength="20" value="${esc(r?.name||'')}" placeholder="A09"></label><label>Sewa bulanan (Rp)<input name="price" type="number" required min="1" step="1" value="${r?.price||1250000}"></label><label>Fasilitas / catatan<input name="note" maxlength="150" value="${esc(r?.note||'')}"></label>${r?'<p style="font-size:11px">Harga kamar menjadi acuan untuk penghuni baru. Ubah harga tenure yang disepakati lewat data penghuni; catatan periode lama tetap dipertahankan.</p>':''}<div class="actions"><button type="button" class="secondary" onclick="closeModal()">Batal</button><button class="primary">Simpan kamar</button></div></form>`);$('#room-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return;if(state.rooms.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))return toast('Nama kamar sudah digunakan.');let d={id:id||crypto.randomUUID(),name,price:Number(f.get('price')),note:f.get('note').trim()};r?Object.assign(r,d):state.rooms.push(d);if(save()){closeModal();render();toast('Kamar tersimpan.')}}}
function templateOptions(selected){return state.templates.map(item=>`<option value="${esc(item.id)}" ${item.id===selected?'selected':''}>${esc(item.name)}</option>`).join('')}
function settingsHTML(){
 const current=state.templates.find(item=>item.id===selectedTemplate)||state.templates[0];selectedTemplate=current.id;
 return `<section class="panel"><div class="settings-body"><div class="settings-title"><h2 style="font:700 16px Manrope">Template chat WhatsApp</h2><button class="secondary" onclick="newTemplate()">＋ Template baru</button></div><p>Pilih template untuk pengingat, perpanjangan, atau tindak lanjut. Semua dapat disesuaikan.</p><label>Pilih template<select id="settings-template" onchange="selectedTemplate=this.value;render()">${templateOptions(current.id)}</select></label><label>Nama template<input id="template-name" maxlength="70" value="${esc(current.name)}"></label><label>Isi pesan<textarea id="template" rows="9">${esc(current.body)}</textarea></label><p class="template-tokens">Variabel: {nama}, {kamar}, {bulan}, {periode}, {nominal}, {tanggal}, {tenure}, {akhir}.</p><div class="actions template-actions"><button class="danger" onclick="deleteTemplate()" ${state.templates.length===1?'disabled':''}>Hapus template</button><button class="primary" onclick="saveTemplate()">Simpan template</button></div><div class="hint">{nominal} adalah total sewa satu tenure. {akhir} adalah akhir periode saat ini; template perpanjangan dapat dipakai meski sewa sudah lunas.<br>Pengiriman dan konfirmasi tetap manual. Belum ada notifikasi saat situs ditutup.</div><h3 style="margin-top:30px">Data prototipe</h3><p>Data dan bukti disimpan di browser ini. Ekspor JSON untuk menyimpan salinan.</p><button class="secondary" onclick="exportData()">↓ Ekspor data</button></div></section>`;
}
function newTemplate(){modal('Template chat baru',`<form id="template-form"><label>Nama template<input name="name" required maxlength="70" placeholder="Misalnya: Konfirmasi tenure baru"></label><label>Isi pesan<textarea name="body" required rows="7" placeholder="Halo Kak {nama}, …"></textarea></label><p style="font-size:11px">Variabel: {nama}, {kamar}, {periode}, {nominal}, {tanggal}, {tenure}, {akhir}.</p><div class="actions"><button type="button" class="secondary" onclick="closeModal()">Batal</button><button class="primary">Simpan template baru</button></div></form>`);$('#template-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),data={id:crypto.randomUUID(),name:f.get('name').trim(),body:f.get('body').trim()};if(!data.name||!data.body)return;if(mutateAndSave(()=>state.templates.push(data))){selectedTemplate=data.id;closeModal();go('settings');toast('Template baru tersimpan.')}}}
function deleteTemplate(){if(state.templates.length===1)return;modal('Hapus template?',`<p>Template ini akan dihapus. Pesan yang sudah ditandai terkirim tetap tersimpan.</p><div class="actions"><button class="secondary" onclick="closeModal()">Batal</button><button class="primary" id="confirm-delete">Hapus template</button></div>`);$('#confirm-delete').onclick=()=>{if(mutateAndSave(()=>state.templates=state.templates.filter(t=>t.id!==selectedTemplate))){selectedTemplate=state.templates[0].id;closeModal();render();toast('Template dihapus.')}}}

function saveTemplate(){
 const name=$('#template-name').value.trim(),body=$('#template').value.trim();if(!name||!body)return toast('Isi nama dan pesan template terlebih dahulu.');
 if(mutateAndSave(()=>{const item=state.templates.find(t=>t.id===selectedTemplate);item.name=name;item.body=body})){render();toast('Template chat tersimpan.')}
}
function exportData(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kost-rapi-'+localDate(today)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$$('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#record-payment').onclick=()=>recordPayment();$('#close').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}};$('#prev').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);render()};$('#next').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);render()};